python3 - <<'E'
p='src/cart.js'
s=open(p).read()
s=s.replace("""function cartTotal(items) {
  let total = 0;
  for (let i = 1; i < items.length; i++) {
    total += items[i].price * items[i].qty;
  }
  return total;
}
""","""function cartSubtotal(items) {
  let total = 0;
  for (let i = 0; i < items.length; i++) {
    total += items[i].price * items[i].qty;
  }
  return total;
}

// Returns the amount (in cents) a discount takes off the given subtotal.
// discount is { type: 'percent', value } (0-100) or { type: 'fixed', value } (cents).
// The result is never more than the subtotal, so totals can't go negative.
function discountAmount(subtotal, discount) {
  if (!discount) return 0;
  let amount;
  if (discount.type === 'percent') {
    amount = Math.round(subtotal * discount.value / 100);
  } else if (discount.type === 'fixed') {
    amount = discount.value;
  } else {
    throw new Error('Unknown discount type: ' + discount.type);
  }
  return Math.max(0, Math.min(amount, subtotal));
}

// Returns the cart total after the optional discount is applied.
function cartTotal(items, discount) {
  const subtotal = cartSubtotal(items);
  return subtotal - discountAmount(subtotal, discount);
}
""")
s=s.replace("""function cartLabel(items) {
  return 'Total: ' + formatPrice(cartTotal(items));""","""function cartLabel(items, discount) {
  return 'Total: ' + formatPrice(cartTotal(items, discount));""")
s=s.replace("{ cartTotal, cartLabel }","{ cartTotal, cartLabel, discountAmount }")
open(p,'w').write(s)
p='test/cart.test.js'
s=open(p).read()
s=s.replace("{ cartTotal, cartLabel }","{ cartTotal, cartLabel, discountAmount }")
s+="""
const items = [{ price: 1000, qty: 2 }, { price: 500, qty: 1 }];

test('cartTotal applies a percent discount', () => {
  assert.strictEqual(cartTotal(items, { type: 'percent', value: 10 }), 2250);
});

test('cartTotal applies a fixed discount', () => {
  assert.strictEqual(cartTotal(items, { type: 'fixed', value: 300 }), 2200);
});

test('discount never exceeds the subtotal', () => {
  assert.strictEqual(cartTotal(items, { type: 'fixed', value: 99999 }), 0);
  assert.strictEqual(discountAmount(100, { type: 'percent', value: 150 }), 100);
});

test('unknown discount type throws', () => {
  assert.throws(() => cartTotal(items, { type: 'bogus', value: 1 }));
});

test('cartLabel reflects the discount', () => {
  assert.strictEqual(cartLabel(items, { type: 'fixed', value: 500 }), 'Total: $20.00');
});
"""
open(p,'w').write(s)
E
