const { formatPrice } = require('../legacy/format');

// Retruns the sum of price * qty for every item.
function cartSubtotal(items) {
  let total = 0;
  for (let i = 0; i < items.length; i++) {
    total += items[i].price * items[i].qty;
  }
  return total;
}

// Returns the amount (in cents) a discount takes off the given subtotal.
// discount is { type: 'percent', value } (0-100) or { type: 'fixed', value } (cents).
// The result is never more than the subtotal, so totals can't go negative.
function discountAmount(subtotal, discount) {
  if (!discount) return 0;
  let amount;
  if (discount.type === 'percent') {
    amount = Math.round(subtotal * discount.value / 100);
  } else if (discount.type === 'fixed') {
    amount = discount.value;
  } else {
    throw new Error('Unknown discount type: ' + discount.type);
  }
  return Math.max(0, Math.min(amount, subtotal));
}

// Returns the cart total after the optional discount is applied.
function cartTotal(items, discount) {
  const subtotal = cartSubtotal(items);
  return subtotal - discountAmount(subtotal, discount);
}

function cartLabel(items, discount) {
  return 'Total: ' + formatPrice(cartTotal(items, discount));
}

function oldShippingFee(items) {
    var fee = 0;
    if (items.length > 0) { fee = 499 }
    return fee
}

